CREATE TABLE `local_recovery_shared_history` (
	`workspace_id` text NOT NULL,
	`device_id` text NOT NULL,
	`epoch_id` text NOT NULL,
	`checkpoint_id` text NOT NULL,
	`descriptor` text NOT NULL,
	`local_descriptor` text NOT NULL,
	`created_at` integer NOT NULL,
	PRIMARY KEY(`workspace_id`, `device_id`, `epoch_id`, `checkpoint_id`),
	CONSTRAINT "local_recovery_shared_history_identity" CHECK(length(trim("local_recovery_shared_history"."workspace_id")) BETWEEN 1 AND 1000 AND instr("local_recovery_shared_history"."workspace_id",char(0))=0 AND length(trim("local_recovery_shared_history"."device_id")) BETWEEN 1 AND 1000 AND instr("local_recovery_shared_history"."device_id",char(0))=0 AND length(trim("local_recovery_shared_history"."epoch_id")) BETWEEN 1 AND 1000 AND instr("local_recovery_shared_history"."epoch_id",char(0))=0 AND length(trim("local_recovery_shared_history"."checkpoint_id")) BETWEEN 1 AND 1000 AND instr("local_recovery_shared_history"."checkpoint_id",char(0))=0),
	CONSTRAINT "local_recovery_shared_history_descriptor" CHECK(json_valid("local_recovery_shared_history"."descriptor") AND json_type("local_recovery_shared_history"."descriptor",'$.version') IS 'integer' AND json_extract("local_recovery_shared_history"."descriptor",'$.version') IS 1 AND json_extract("local_recovery_shared_history"."descriptor",'$.identity.workspaceId') IS "local_recovery_shared_history"."workspace_id" AND json_extract("local_recovery_shared_history"."descriptor",'$.identity.deviceId') IS "local_recovery_shared_history"."device_id" AND json_extract("local_recovery_shared_history"."descriptor",'$.identity.epochId') IS "local_recovery_shared_history"."epoch_id" AND json_extract("local_recovery_shared_history"."descriptor",'$.identity.checkpointId') IS "local_recovery_shared_history"."checkpoint_id"),
	CONSTRAINT "local_recovery_shared_history_local_descriptor" CHECK(json_valid("local_recovery_shared_history"."local_descriptor") AND json_type("local_recovery_shared_history"."local_descriptor",'$.version') IS 'integer' AND json_extract("local_recovery_shared_history"."local_descriptor",'$.version') IS 1 AND json_extract("local_recovery_shared_history"."local_descriptor",'$.identity.workspaceId') IS "local_recovery_shared_history"."workspace_id" AND json_extract("local_recovery_shared_history"."local_descriptor",'$.identity.deviceId') IS "local_recovery_shared_history"."device_id" AND json_extract("local_recovery_shared_history"."local_descriptor",'$.identity.epochId') IS "local_recovery_shared_history"."epoch_id" AND json_extract("local_recovery_shared_history"."local_descriptor",'$.identity.checkpointId') IS "local_recovery_shared_history"."checkpoint_id" AND json_extract("local_recovery_shared_history"."local_descriptor",'$.identity.schemaId') IS json_extract("local_recovery_shared_history"."descriptor",'$.identity.schemaId'))
);
